public class InnerHarnessHarnessModelConfigurationFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessModelConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessModelConfiguration>
{

    internal InnerHarnessHarnessLiteLlmModelConfigFactory LiteLlmModelConfigFactory { get; set; }

    internal InnerHarnessHarnessBedrockModelConfigFactory BedrockModelConfigFactory { get; set; }

    internal InnerHarnessHarnessGeminiModelConfigFactory GeminiModelConfigFactory { get; set; }

    internal InnerHarnessHarnessOpenAiModelConfigFactory OpenAiModelConfigFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessModelConfiguration Create()
    {
        var harnessModelConfigurationResult = CreateHarnessModelConfiguration();
        factoryAction?.Invoke(harnessModelConfigurationResult);

        return harnessModelConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessModelConfiguration CreateHarnessModelConfiguration()
    {
        var harnessModelConfigurationResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessModelConfiguration();

        return harnessModelConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessModelConfiguration result)
    {
        base.CreateChildren(result);

        result.LiteLlmModelConfig ??= LiteLlmModelConfigFactory?.Build();
        result.BedrockModelConfig ??= BedrockModelConfigFactory?.Build();
        result.GeminiModelConfig ??= GeminiModelConfigFactory?.Build();
        result.OpenAiModelConfig ??= OpenAiModelConfigFactory?.Build();
    }

} // End Of Class

